const fs = require('fs');
const path = require('path');

// ============================================================
// generar_461_clasificador.js
// ============================================================
// Corrige las CAUSAS RAIZ de la auditoria. No son parches por caso: son
// cinco cambios estructurales.
//
// 1. LA CATEGORIA YA NO SE HEREDA POR NO ENTENDER
//    Antes, si el clasificador daba cero puntos y la frase empezaba con
//    "y", asumia continuacion. Un error de tipeo bastaba: "Y si proxima
//    desparaCitada?" daba cero, heredaba vacunas y respondia Felocell.
//    Ahora se exige que la frase PIDA continuar. Si no entiende, lo
//    admite — que es lo correcto.
//
// 2. EL TEMA 'VITALES' SE PARTIO EN CUATRO
//    Agua, temperatura, corazon e higiene dental eran UN tema con
//    cuatro opciones que ROTABAN. Por eso preguntar "¿cuanta agua
//    necesita?" cuatro veces devolvia las cuatro cosas en orden. La
//    rotacion solo tiene sentido cuando las opciones son variaciones de
//    lo mismo, como en ansiedad.
//
// 3. EL 'RESUMEN' DEJO DE COMPETIR
//    "¿Como ha estado su ANIMO?" caia en resumen porque la frase "como
//    ha estado" es mas larga que "animo". Ahora el resumen se evalua al
//    final, solo si nada especifico calzo.
//
// 4. EXISTEN LOS PERIODOS
//    Antes todo respondia "los ultimos 30 dias" aunque se preguntara
//    por la ultima semana. Ahora se reconocen hoy, ayer, ultimos 3/7/14
//    dias, esta semana, este mes, ultimos 3 meses, este año,
//    recientemente y ultimamente. Y la respuesta dice cual se uso.
//
// 5. SE COMPARA POR PALABRAS, NO POR TEXTO LITERAL
//    "¿Como deben ser SUS heces?" no coincidia con "como deben ser LAS
//    heces" por una palabra en medio. Ahora una frase calza si todas
//    sus palabras estan, en cualquier orden.
//
// Y SE SEPARA EDUCATIVO DE DATOS por tiempo verbal:
//   "¿como HAN SIDO sus heces?"  -> sus registros
//   "¿como DEBEN SER sus heces?" -> informacion general
//
// PROBADO con 16 casos, incluidos todos los que reporto Casandra.
//
// REQUISITO: script 460 desplegado (el aislamiento de mascotas).
//
// Si algo no calza, ABORTA sin escribir.
// ============================================================

const RUTA = 'components/ChiquiChat.tsx';
const CHAT_B64 = '';

function abortar(motivo) {
  console.log('');
  console.log('ABORTADO: ' + motivo);
  console.log('No se modifico ningun archivo. Avisale a Claude lo que dice este mensaje.');
  process.exit(1);
}

const destino = path.join(process.cwd(), RUTA);
if (!fs.existsSync(destino)) {
  abortar('no se encontro ' + RUTA + '.');
}

const actual = fs.readFileSync(destino, 'utf8');
if (actual.includes('const PERIODOS')) {
  abortar('el clasificador ya esta corregido. Parece que este script ya se corrio.');
}
if (!actual.includes('mascotaId?: string')) {
  abortar('falta el script 460 (aislamiento de mascotas). Correlo primero: es el critico.');
}

const comp = Buffer.from(CHAT_B64, 'base64').toString('utf8');

const REQUERIDOS = [
  "'use client'", 'export default function ChiquiChat',
  'function coincide', 'const PERIODOS', 'function detectarPeriodo',
  'function filtrarPorPeriodo', 'PIDE_CONTINUAR', 'SENAL_EDUCATIVA',
  "tema: 'agua'", "tema: 'temperatura'", "tema: 'corazon'", "tema: 'dientes'",
  'mascotaId?: string',
];
for (const r of REQUERIDOS) {
  if (!comp.includes(r)) {
    abortar('el contenido nuevo no incluye [' + r + ']. Script corrupto, no se escribio nada.');
  }
}
// El tema que mezclaba categorias no puede seguir.
if (comp.includes("tema: 'vitales'")) {
  abortar("el tema 'vitales' sigue existiendo: rotaria entre agua, temperatura y dientes.");
}
console.log('  OK  vitales partido en cuatro temas');

// El resumen tiene que saltarse en el bucle principal.
if (!comp.includes("if (i.tema === 'resumen') continue")) {
  abortar('el resumen sigue compitiendo con los temas especificos.');
}
console.log('  OK  el resumen ya no compite');

if (comp.split('type Tema =').length - 1 !== 1) {
  abortar('type Tema deberia declararse una sola vez.');
}
console.log('  OK  el contenido nuevo esta completo');

fs.writeFileSync(destino, comp, 'utf8');
console.log('');
console.log('OK: ' + RUTA);
console.log('');
console.log('AVISO: falta que ChiquiFlotante y Analisis pasen hoyISO, o los');
console.log('periodos no podran recortarse. Eso va en el siguiente script.');
console.log('');
console.log('Listo.');
